-- Description: Processe the event ID 3 race results:
SET SCHEMA endurancetrio_hub;

-- Update existing athletes
UPDATE athlete SET known_name = 'Luis Sousa' WHERE id = 93;
UPDATE athlete SET known_name = 'Paulo Gomes' WHERE id = 98;
UPDATE athlete SET known_name = 'Luis Gonçalves' WHERE id = 101;
UPDATE athlete SET known_name = 'João Macedo' WHERE id = 108;
UPDATE athlete SET known_name = 'José Sousa' WHERE id = 148;
UPDATE athlete SET known_name = 'Jorge Vaz' WHERE id = 158;

-- Insert new athletes

ALTER SEQUENCE endurancetrio_hub.seq_athlete_id RESTART WITH 210;

-- Update existing race's result_status
UPDATE race SET result_status = 'COMPLETE' WHERE id IN (7, 8, 9);

-- Insert individual results

ALTER SEQUENCE endurancetrio_hub.seq_individual_result_id RESTART WITH 517;
